<?php $rows=$service->people($q); ?>
<div class="toolbar"><form class="filters"><input type="hidden" name="page" value="people"><label class="sr-only" for="q">Buscar colaborador</label><input id="q" name="q" value="<?= e($q) ?>" placeholder="Buscar nome ou login"><button class="secondary">Buscar</button></form><a class="button" href="<?= e(url('person-form')) ?>">+ Novo colaborador</a></div>
<section class="card"><div class="section-head"><h2>Pessoas <small><?= count($rows) ?> registros</small></h2></div><div class="table-wrap"><table><thead><tr><th>Nome / login</th><th>Departamento</th><th>Cargo</th><th>Campus</th><th>Ações</th></tr></thead><tbody><?php foreach($rows as $c): ?><tr><td><strong><?= e($c['nome']) ?></strong><small><?= e($c['login']) ?></small></td><td><?= e($c['departamento']) ?></td><td><?= e($c['cargo']) ?></td><td><?= e($c['campus']) ?></td><td><a href="<?= e(url('person-form',['login'=>$c['login']])) ?>">Editar</a></td></tr><?php endforeach ?><?php if(!$rows): ?><tr><td colspan="5" class="empty">Nenhum colaborador encontrado.</td></tr><?php endif ?></tbody></table></div></section>
